        `,armorStyles:[{name:"D\u014D-maru",descrip:"Iron or leather plates laced together with silk or leather cords.",chosen:!1},{name:"Kusari Armor",descrip:"Interlocking metal rings.",chosen:!1}],rerollable:!0},{tier:3,descrip:`
